diff --git a/axocoatl-cli/src/main.rs b/axocoatl-cli/src/main.rs
index 9036da73..10dcda00 100644
--- a/axocoatl-cli/src/main.rs
+++ b/axocoatl-cli/src/main.rs
@@ -4771,6 +4771,21 @@ mod tests {
         );
     }

+    #[test]
+    fn shell_word_handles_spaces_and_quotes() {
+        // A path containing a space comes back single-quoted
+        assert_eq!(
+            shell_word(std::path::Path::new("/path with spaces/config.yaml")),
+            "'/path with spaces/config.yaml'"
+        );
+        
+        // A path containing a single quote has it escaped
+        assert_eq!(
+            shell_word(std::path::Path::new("/path'with'quotes/config.yaml")),
+            r"'/path'\\''with'\\''quotes/config.yaml'"
+        );
+    }
+
     #[test]
     fn plain_server_url_brackets_ipv6_hosts() {
         assert_eq!(plain_server_url("0.0.0.0", 8080), "http://0.0.0.0:8080/");

